(async()=>{if(!globalThis.cookieStore)return {};const out={events:[]};cookieStore.onchange=e=>out.events.push({changed:e.changed,deleted:e.deleted});await cookieStore.set('cs_a','one');out.get=await cookieStore.get('cs_a');await cookieStore.set('cs_a','two');await cookieStore.set({name:'cs_b',value:'v',sameSite:'lax'});out.all=await cookieStore.getAll();out.doc=document.cookie;await cookieStore.delete('cs_a');out.none=await cookieStore.get('cs_a');document.cookie='cs_c=c;path=/';await new Promise(r=>setTimeout(r,50));out.final=await cookieStore.getAll();return JSON.stringify(out)})()